import * as C from './compare-records-core.mjs';
import {referenceScalesPage,referenceGrownup,referenceSignedText} from './reference-scales-ui.mjs';
import {hearButton} from './play-media.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy=structuredClone;
const ratio=x=>typeof x==='number'?{n:x,d:1}:x;
const fmt=x=>C.formatCompare(ratio(x));
const number=x=>`<span data-cr-number data-cr-say="${esc(fmt(x).replace('/',' over '))}">${esc(fmt(x))}</span>`;
const minutes=x=>`${number(x)} ${ratio(x).n===ratio(x).d?'minute':'minutes'}`;
const button=(attrs,text,{pressed=null,disabled=false}={})=>`<button type="button" ${attrs}${pressed===null?'':` aria-pressed="${pressed}"`}${disabled?' disabled':''}>${esc(text)}</button>`;
const pages=['Compare the records','Look closer','Make a case'];
const purposes={typical:'A typical recorded trip',total:'Total time in these records',variation:'Variation in recorded times'};
const helps={typical:'Compare the middle values and inspect the whole drawing.',total:'Mean uses every recorded value. Open Show how to see the total and count for each list.',variation:'Compare the ranges and inspect the gaps and stacks; range does not describe every detail.'};
const definitions={mean:'Mean shares the total equally among the recorded values.',median:'Median is the middle of the values in order. With an even count, use the number halfway between the two middle values.',range:'Range is highest minus lowest. It uses only the two ends, not every difference in the list.'};
const newUI=()=>({page:0,workedOpen:false,step:0,sourceOpen:false,glossaryOpen:false,aboutOpen:false,summaryOpen:false});
let visit=null,generation=0;
export function resetCompareVisit(){visit=null;generation++;}
function session(state,owner){if(!visit||visit.state!==state||visit.owner!==owner)visit={state,owner,slots:new Map(),keptUI:new Map(),current:null,qualified:new Set(),notice:''};return visit;}
function draft(source){return {source,focus:'mean',aside:false,workingsShown:false,secondaryWorkingsSeen:false,workedSeen:0,narration:false,purpose:null,...(C.isReferenceScaleMode(source)?{referenceView:C.newReferenceView()}:{} )};}
function active(s,state){
 if(!s.current)return null;
 if(s.current.kind==='draft'){const entry=s.slots.get(s.current.key);return entry?{...entry,slot:s.current.key,mutable:true}:null;}
 const item=C.compareRecordsView(state).items.find(i=>i.id===s.current.id&&i.readable);if(!item)return null;
 if(!s.keptUI.has(item.id))s.keptUI.set(item.id,newUI());
 return {work:item.raw,ui:s.keptUI.get(item.id),id:item.id,mutable:false};
}
function footer(){return `<footer><a href="#learn/science/ledger">The ledger and the rain gauge</a><a href="#learn/math/timing-desk">The message and the water</a><a href="#learn/math/estimates">Courier Estimates</a><a href="#learn/math">Math explorations</a><a href="#notes">Grown-up notes</a></footer>`;}
function summaries(w){
 return `<table data-cr-summarytable class="cr-summaries"><caption>Recorded minutes · count in trips</caption><thead><tr><th scope="col">Summary</th>${w.source.groups.map(g=>`<th scope="col">${esc(g.label)}</th>`).join('')}</tr></thead><tbody>${[['Count','n'],['Mean','mean'],['Median','median'],['Range','range']].map(([label,key])=>`<tr${w.focus===key?' class="cr-selected-summary"':''}><th scope="row">${label}</th>${w.source.groups.map(g=>`<td data-cr-summary="${key}" data-cr-group="${esc(g.id)}">${number(C.recordSummary(g.records)[key])}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
}
function plot(c){
 const {work:w,ui}=c,s=w.source,geometry=C.compareGeometry(s),note=C.comparisonNote(s),secondary=ui.page===1&&w.aside&&note?C.secondarySummary(w):null;
 const drawing=geometry.groups.map((g,i)=>{
  const original=C.recordSummary(s.groups[i].records),shown=secondary&&note.groupIndex===i?secondary:original,y=g.baseline-20*geometry.lanes-20;
  const highlight=w.focus==='range'?`<path data-cr-highlight="range" data-cr-group="${esc(g.id)}" d="M${60+500*shown.min/s.axis.max} ${y}H${60+500*shown.max/s.axis.max}M${60+500*shown.min/s.axis.max} ${y}v8M${60+500*shown.max/s.axis.max} ${y}v8"/>`:`<line data-cr-highlight="${w.focus}" data-cr-group="${esc(g.id)}" x1="${60+500*C.compareNumber(shown[w.focus])/s.axis.max}" x2="${60+500*C.compareNumber(shown[w.focus])/s.axis.max}" y1="${y}" y2="${g.baseline+18}"/>`;
  return `<g class="cr-group-${i}"><line class="cr-axis" x1="60" x2="560" y1="${g.baseline+18}" y2="${g.baseline+18}"/>${geometry.ticks.map(t=>`<path class="cr-axis" d="M${t.x} ${g.baseline+18}v6"/>${t.label?`<text data-cr-tick x="${t.x}" y="${g.baseline+60}" text-anchor="middle">${esc(t.value)}</text>`:''}`).join('')}${highlight}${g.points.map(p=>{const aside=!!(ui.page===1&&w.aside&&note&&note.groupIndex===i&&note.recordId===p.id);return `<circle data-cr-dot data-cr-group="${esc(g.id)}" data-cr-id="${esc(p.id)}" data-cr-value="${p.value}"${aside?' data-cr-aside-dot':''} cx="${p.x}" cy="${p.y}" r="6" stroke-width="2"><title>${esc(g.label)} · ${esc(p.id)} · ${p.value} minutes${aside?' · set aside, retained in original records':''}</title></circle>${aside?`<path class="cr-cross" d="M${p.x-4} ${p.y-4}l8 8m-8 0l8-8"/>`:''}`;}).join('')}</g>`;
 }).join('');
 const description=s.groups.map(g=>`${g.label}: ${g.records.map(r=>r.value).join(', ')} minutes`).join('. ');
 return `<figure class="cr-paper"><div class="cr-plot-key">${s.groups.map((g,i)=>`<p><span class="cr-swatch cr-swatch-${i}" aria-hidden="true"></span><strong>${i===0?'Top':'Bottom'}: ${esc(g.label)}</strong></p>`).join('')}</div><svg data-cr-plot viewBox="0 0 600 ${geometry.height}" role="img" aria-label="${esc(`Original recorded minutes on a common horizontal scale from zero to ${s.axis.max}. ${description}. Vertical lanes only keep dots apart.`)}">${drawing}</svg><figcaption>Each dot is one recorded trip. Nearby dots stack so you can see them. Read minutes across. A dot sits higher only to keep nearby dots apart. Both drawings use the same scale.</figcaption>${secondary?`<p class="cr-plot-note">${esc(s.groups[note.groupIndex].label)} highlight: secondary comparison · ${esc(note.recordId)} set aside. The hollow, crossed dot stays at its original position.</p>`:''}</figure>`;
}
function workingsFor(group,stats,secondary=false){
 const ordered=group.records.map((r,i)=>({...r,index:i})).sort((a,b)=>a.value-b.value||a.index-b.index),middle=Math.floor(ordered.length/2);
 return `<section${secondary?' data-cr-secondary-workings':''}><h3>${esc(group.label)} · ${secondary?'secondary comparison':`all ${stats.n} recorded trips`}</h3><p>Total: ${minutes(stats.total)}. ${number(stats.total)} ÷ ${number(stats.n)} = ${minutes(stats.mean)} per recorded trip.</p><p>In order: ${ordered.map(r=>number(r.value)).join(', ')}.</p><p>${ordered.length%2?`The middle value is ${minutes(stats.median)}.`:`The two middle values are ${number(ordered[middle-1].value)} and ${number(ordered[middle].value)}. (${number(ordered[middle-1].value)} + ${number(ordered[middle].value)}) ÷ 2 = ${minutes(stats.median)}.`}</p><p>Range: ${number(stats.max)} − ${number(stats.min)} = ${minutes(stats.range)}.</p></section>`;
}
function workings(c){
 const {work:w,ui,mutable}=c,note=C.comparisonNote(w.source),secondary=w.aside&&note&&ui.page!==0;
 const control=mutable?button('data-cr-workings',w.workingsShown?'Hide workings':'Show how',{pressed:w.workingsShown}):!w.workingsShown?'<p>Try this comparison again to open the workings.</p>':'';
 if(!w.workingsShown)return control;
 return `<section class="cr-workings" data-cr-workings-body><h3 id="cr-workings-heading" tabindex="-1">Show how</h3>${w.source.groups.map(g=>workingsFor(g,C.recordSummary(g.records))).join('')}${secondary?mutable||w.secondaryWorkingsSeen===true?workingsFor({...w.source.groups[note.groupIndex],records:w.source.groups[note.groupIndex].records.filter(r=>r.id!==note.recordId)},C.secondarySummary(w),true):'<p>Earlier secondary workings were not recorded here. Try this comparison again to open them.</p>':''}${control}</section>`;
}
function closer(c){
 const {work:w,mutable}=c,note=C.comparisonNote(w.source);
 if(!note){const stats=w.source.groups.map(g=>C.recordSummary(g.records)),equal=['mean','median'].every(k=>stats[0][k].n*stats[1][k].d===stats[1][k].n*stats[0][k].d);return `<section class="cr-question"><h3>What does the center leave out?</h3>${w.aside?'<p>Your earlier secondary choice is retained, but its record cannot be identified here. The original summaries are still open.</p>':'<p>These records have no separately noted trip to set aside.</p>'}<p>${equal?'Their centers agree. Compare their spreads before saying the lists are alike.':'Compare their centers and spreads before saying the lists are alike.'}</p><p>Which single summary might hide how spread out these trips were?</p>${w.aside&&mutable?button('data-cr-aside','Use all records'):''}</section>`;}
 const group=w.source.groups[note.groupIndex],all=C.recordSummary(group.records),secondary=C.secondarySummary(w);
 return `<section class="cr-question"><h3>Read the note before setting a trip aside</h3><blockquote>${esc(note.note)}</blockquote><p>${esc(group.label)} · ${esc(note.recordId)} · ${minutes(note.record.value)}</p>${mutable?button('data-cr-aside',w.aside?'Use all records':'Set it aside in a comparison',{pressed:w.aside}):!w.aside?'<p>Try this comparison again to explore setting a record aside.</p>':''}${w.aside?`<section class="cr-secondary"><h3>Secondary comparison · ${esc(note.recordId)} set aside</h3><p>The ${number(note.record.value)}-minute trip stays in the original records. It is hollow and crossed in this drawing, not deleted.</p>${secondaryTable(group,all,secondary)}<p>Compare which summaries changed, and by how much.</p><p>This comparison leaves out one named record. That answers a narrower question. Read its note and decide whether setting it aside fits your question. A surprising number alone is not a recording mistake.</p><p>These remaining observations do not promise a future trip time. This bench does not establish which other trips had the same conditions.</p><p>A different list might move its median more. Inspect the actual values.</p></section>`:''}</section>`;
}
function secondaryTable(group,all,secondary){return `<table class="cr-summaries cr-secondary-table"><caption>${esc(group.label)} · original and secondary lists</caption><thead><tr><th scope="col">Summary</th><th scope="col">All ${all.n} trips</th><th scope="col">${secondary.n} trips · one set aside</th></tr></thead><tbody>${[['Count','n'],['Mean','mean'],['Median','median'],['Range','range']].map(([label,key])=>`<tr><th scope="row">${label}</th><td>${number(all[key])}</td><td>${number(secondary[key])}</td></tr>`).join('')}</tbody></table>`;}
function makeCase(c){
 const {work:w,mutable}=c,note=C.comparisonNote(w.source),secondary=w.aside&&note?C.secondarySummary(w):null;
 return `<section class="cr-question"><h3>${mutable?'Choose what matters for this comparison':'Your chosen purpose'}</h3>${mutable?`<div class="cr-purposes" role="group" aria-label="Purpose of this comparison">${Object.entries(purposes).map(([id,label])=>button(`data-cr-purpose="${id}"`,label,{pressed:w.purpose===id})).join('')}</div>`:`<p>${w.purpose?esc(purposes[w.purpose]):'No purpose was selected. Try this comparison again to choose one.'}</p>`}${w.purpose?`<p class="cr-purpose-help">${esc(helps[w.purpose])}</p>`:''}${secondary?`<h3>Secondary comparison · ${esc(note.recordId)} set aside</h3><blockquote>${esc(note.note)}</blockquote><p>Set-aside record: ${minutes(note.record.value)}. The original remains in your notes.</p>${secondaryTable(w.source.groups[note.groupIndex],C.recordSummary(w.source.groups[note.groupIndex].records),secondary)}`:w.aside?'<p>Your earlier secondary choice is retained, but its record cannot be identified here. The original summaries are still open.</p>':''}<p>Say or write a recommendation. Point to a summary and a detail in the drawing. Name one question these records do not answer.</p><p>Different readers may choose different trade-offs. There is no scored route choice here.</p><p>Your own words stay spoken or on paper. Keeping saves the records and your selected view, not a recording or a marked answer.</p></section>`;
}
function teaching(c){
 const {work:w,ui,mutable}=c,helper=C.compareWorked(w.source);if(!helper)return '<p>An example is not available for these records. You can still compare them.</p>';
 if(!mutable&&!w.workedSeen)return '';
 const control=button('data-cr-worked',ui.workedOpen?'Close example':mutable?'Show a different example':'Earlier teaching',{pressed:ui.workedOpen});
 return ui.workedOpen?`<section class="cr-teaching"><h3 id="cr-teaching-heading" tabindex="-1">Different example</h3>${mutable?`<p>${esc(helper.steps[ui.step])}</p><div class="cr-actions">${button('data-cr-step="-1"','Previous step',{disabled:ui.step===0})}${button('data-cr-step="1"','Next step',{disabled:ui.step===helper.steps.length-1})}</div>`:`<ol>${helper.steps.slice(0,w.workedSeen).map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`}${control}</section>`:control;
}
function sourceFold(w,ui){return `<details data-cr-source-fold${ui.sourceOpen?' open':''}><summary>Source and records</summary><p>${esc(w.source.origin)}</p><p>${esc(w.source.notice)}</p><p>${esc(w.source.purpose)}</p><div class="cr-record-lists">${w.source.groups.map(g=>`<section><h3>${esc(g.label)} · original records</h3><ol>${g.records.map(r=>`<li>${esc(r.id)}: ${minutes(r.value)}${typeof r.note==='string'?` · ${esc(r.note)}`:''}</li>`).join('')}</ol></section>`).join('')}</div></details>`;}
function chooser(s,state){
 const view=C.compareRecordsView(state);
 return `<section><h2 id="cr-chooser" tabindex="-1">Which records shall we compare?</h2><p>Compare invented trip records or model scale readings. Choose one example and put its drawings side by side.</p><div class="cr-choices">${['courier','parcels','reference-scales'].map(id=>{const source=C.compareSource(id);return `<section><h3>${esc(source.title)}</h3><p>${esc(source.purpose)}</p>${button(`data-cr-start="${id}"`,id==='reference-scales'?'Reference Scales':'Start these records')}</section>`;}).join('')}</div>${s.slots.size?`<h3>Unkept models in this visit</h3><div class="cr-history">${[...s.slots].map(([key,entry],i)=>button(`data-cr-resume="${esc(key)}"`,`Continue model ${i+1} · ${entry.work.source.title}`)).join('')}</div>`:''}<h3>Earlier kept comparisons</h3><div class="cr-history">${view.items.length?view.items.map(item=>item.readable?button(`data-cr-open="${esc(item.id)}"`,`Comparison ${item.index+1} · ${item.raw.source.title}`):'<p>Earlier comparison retained · its original stays in your notes.</p>').join(''):'<p>No kept comparisons yet.</p>'}</div>${view.status==='unsupported'?'<p>Earlier comparisons stay in your notes. This format cannot accept another kept comparison here.</p>':''}</section>`;
}
export function comparePage(state,owner){
 const s=session(state,owner),c=active(s,state),w=c?.work;
 if(c&&C.isReferenceScaleMode(w.source))return referenceScalesPage(c,s.notice);
 const instruction=!c?'':c.ui.page===0?c.mutable?'Highlight a center or spread. What does it show about both lists?':'Read this comparison’s highlights.':c.ui.page===1?'Inspect a note, or compare what the centers leave out.':c.mutable?'Choose what matters. Tell someone what the records support—and what they leave open.':'Read your purpose and discuss what the records leave open.';
 return `<div class="cr-page" data-cr-root${c&&!c.mutable?' data-cr-kept':''}><header><a href="#learn/math">Back to math explorations</a><h1>The Compare Shelf</h1><p>${c?'Made-up route records. They are not advice about safe crossings or a promise about the next trip.':'Invented examples for thinking together, not verified measurements or predictions.'}</p></header>${c?`<section data-cr-turn><h2 id="cr-heading" tabindex="-1">${pages[c.ui.page]}</h2><p class="cr-instruction">${instruction}</p><p class="cr-context">${esc(w.source.title)} · original observations in minutes</p><nav class="cr-tabs" aria-label="Comparison turns">${pages.map((title,i)=>button(`data-cr-page="${i}"`,title,{pressed:c.ui.page===i})).join('')}</nav><div class="cr-workbench">${plot(c)}<section class="cr-summary-controls"><h3>${c.mutable?'Highlight a summary':'Saved highlight'}: ${w.focus[0].toUpperCase()+w.focus.slice(1)}</h3>${c.mutable?`<div class="cr-focus" role="group" aria-label="Highlight a summary">${['mean','median','range'].map(id=>button(`data-cr-focus="${id}"`,id[0].toUpperCase()+id.slice(1),{pressed:w.focus===id})).join('')}</div>`:''}<p>${esc(definitions[w.focus])}</p>${summaries(w)}<p>A mean alone does not show how spread out the trips were. A range alone does not give their center.</p></section></div>${c.ui.page===0?`<p>These summaries describe the listed observations. They do not promise a future journey time.</p>`:c.ui.page===1?closer(c):makeCase(c)}${workings(c)}${c.ui.page===0?teaching(c):''}${sourceFold(w,c.ui)}<div class="cr-actions cr-main-actions">${button(`data-cr-page="${c.ui.page-1}"`,'Previous',{disabled:c.ui.page===0})}${button(`data-cr-page="${c.ui.page+1}"`,'Next',{disabled:c.ui.page===2})}${c.mutable?button('data-cr-keep','Keep this comparison'):button(`data-cr-again="${esc(c.id)}"`,'Try this comparison again')}${hearButton('','Hear this turn').replace('<button','<button data-cr-hear')}${button('data-cr-choose','Choose records')}</div><p>${c.mutable?'Unkept choices stay in this visit. Keep a comparison before leaving if you want it later.':'This kept comparison stays as it was. Try it again to change a choice or open more teaching.'}</p></section>`:chooser(s,state)}<p id="cr-status" role="status" tabindex="-1" class="cr-status${s.notice?'':' sr-only'}">${esc(s.notice)}</p>${footer()}</div>`;
}

export function bindCompare(state,ctx){
 const root=document.querySelector('[data-cr-root]');if(!root)return;
 const owner=ctx.explorerId(),s=session(state,owner),bound=++generation;
 const live=node=>root.isConnected&&node?.isConnected&&visit===s&&bound===generation&&location.hash==='#learn/math/compare-records'&&ctx.notebook()===state&&ctx.explorerId()===owner&&ctx.isActive?.()!==false;
 let rollback=null;
 const snapshot=()=>{const slots=new Map(s.slots),keptUI=new Map(s.keptUI);if(s.current?.kind==='draft'&&slots.has(s.current.key))slots.set(s.current.key,copy(slots.get(s.current.key)));if(s.current?.kind==='kept'&&keptUI.has(s.current.id))keptUI.set(s.current.id,copy(keptUI.get(s.current.id)));return {current:s.current,slots,keptUI};};
 const show=(focus='#cr-heading',scroll=false)=>{
  ctx.stopSpeech?.();ctx.stopSound?.();const c=active(s,state);
  if(c?.mutable&&!C.isReferenceScaleMode(c.work.source)&&c.ui.page!==0&&c.work.workingsShown&&c.work.aside&&C.comparisonNote(c.work.source))c.work.secondaryWorkingsSeen=true;
  const pairs=c?C.compareDisplayPairs(c.work,{...c.ui,mutable:c.mutable}).filter(p=>!s.qualified.has(p.join('x'))):[];
  const result=C.recordGivenMath(state,pairs,{canExport:ctx.canExport,exposeFacts:ctx.exposeFacts});
  if(!result.ok){if(rollback){s.current=rollback.current;s.slots=rollback.slots;s.keptUI=rollback.keptUI;}s.notice=rollback?.current?'That view could not open. Your current drawing and choices are still here. Open Grown-up notes to download your work.':'These records could not open without changing earlier number notes. Nothing was changed. Open Grown-up notes to download your work, or return to the ledger.';ctx.render();document.querySelector('#cr-status')?.focus();return;}
  for(const pair of pairs)s.qualified.add(pair.join('x'));if(result.changed)ctx.save?.();ctx.render();const target=document.querySelector(focus)||document.querySelector('#cr-heading');target?.focus({preventScroll:true});if(scroll)target?.scrollIntoView({block:'start'});
 };
 const perform=(node,fn)=>{if(!live(node)||node.disabled)return;rollback=snapshot();s.notice='';try{fn(node);}finally{rollback=null;}};
 const each=(selector,fn)=>root.querySelectorAll(selector).forEach(node=>node.addEventListener('click',()=>perform(node,fn)));
 const editable=fn=>{const c=active(s,state);if(c?.mutable)fn(c);};
 each('[data-cr-start]',b=>{const source=C.compareSource(b.dataset.crStart);if(!source)return;const key=`authored:${source.id}`;if(!s.slots.has(key))s.slots.set(key,{work:draft(source),ui:newUI()});s.current={kind:'draft',key};show('#cr-heading',true);});
 each('[data-cr-resume]',b=>{if(s.slots.has(b.dataset.crResume)){s.current={kind:'draft',key:b.dataset.crResume};show('#cr-heading',true);}});
 each('[data-cr-open]',b=>{const id=b.dataset.crOpen;if(C.compareRecordsView(state).items.some(i=>i.id===id&&i.readable)){s.keptUI.set(id,{...(s.keptUI.get(id)||newUI()),workedOpen:false});s.current={kind:'kept',id};show('#cr-heading',true);}});
 each('[data-cr-again]',b=>{const item=C.compareRecordsView(state).items.find(i=>i.id===b.dataset.crAgain&&i.readable);if(!item)return;const key=`again:${item.id}`;if(!s.slots.has(key)){const {source,focus,aside,workingsShown,secondaryWorkingsSeen,workedSeen,narration,purpose}=item.raw;s.slots.set(key,{work:copy({source,focus,aside,workingsShown,secondaryWorkingsSeen,workedSeen,narration,purpose,...(C.isReferenceScaleMode(source)?{referenceView:copy(item.raw.referenceView)}:{})}),ui:newUI()});}s.current={kind:'draft',key};show('#cr-heading',true);});
 each('[data-cr-choose]',()=>{s.current=null;show('#cr-chooser',true);});
 each('[data-cr-page]',b=>{const c=active(s,state),page=Number(b.dataset.crPage);if(c&&Number.isInteger(page)&&page>=0&&page<=2){c.ui.page=page;show('#cr-heading',true);}});
 each('[data-cr-focus]',b=>editable(c=>{if(['mean','median','range'].includes(b.dataset.crFocus)){c.work.focus=b.dataset.crFocus;show(`[data-cr-focus="${c.work.focus}"]`);}}));
 const referenceEditable=fn=>editable(c=>{if(C.validReferenceScaleWork(c.work))fn(c);});
 each('[data-rs-reference]',()=>referenceEditable(c=>{c.work.referenceView.referenceShown=true;show('#cr-heading');}));
 each('[data-rs-check]',()=>referenceEditable(c=>{c.work.referenceView.checkShown=true;show('#cr-heading',true);}));
 each('[data-rs-adjust-start]',()=>referenceEditable(c=>{const v=c.work.referenceView;if(!(c.ui.page===2?v.checkShown:v.referenceShown))return;v.adjustmentShown=true;const bounds=c.work.source.referenceScales.adjustment;show(v.adjustment>bounds.min?'[data-rs-adjust="-1"]':v.adjustment<bounds.max?'[data-rs-adjust="1"]':'#cr-heading');}));
 each('[data-rs-adjust]',b=>referenceEditable(c=>{const v=c.work.referenceView,bounds=c.work.source.referenceScales.adjustment;if(!v.adjustmentShown||!(c.ui.page===2?v.checkShown:v.referenceShown))return;const action=b.dataset.rsAdjust;if(!['-1','1','reset'].includes(action))return;const next=action==='reset'?0:v.adjustment+Number(action);if(next<bounds.min||next>bounds.max)return;v.adjustment=next;const focus=action==='reset'?(next>bounds.min?'-1':'1'):action==='-1'&&next===bounds.min?'1':action==='1'&&next===bounds.max?'-1':action;show(`[data-rs-adjust="${focus}"]:not(:disabled)`);}));
 for(const [selector,key] of [['[data-rs-about]','aboutOpen'],['[data-rs-summaries]','summaryOpen']])root.querySelector(selector)?.addEventListener('toggle',event=>{if(live(event.target)){const c=active(s,state);if(c)c.ui[key]=event.target.open;ctx.stopSpeech?.();}});
 root.querySelector('[data-rs-glossary]')?.addEventListener('toggle',event=>{if(live(event.target)){const c=active(s,state);if(c)c.ui.glossaryOpen=event.target.open;ctx.stopSpeech?.();}});
 each('[data-cr-workings]',()=>editable(c=>{c.work.workingsShown=!c.work.workingsShown;show(c.work.workingsShown?'#cr-workings-heading':'[data-cr-workings]');}));
 each('[data-cr-aside]',()=>editable(c=>{if(C.comparisonNote(c.work.source)||c.work.aside){c.work.aside=!c.work.aside;show('[data-cr-aside]');}}));
 each('[data-cr-purpose]',b=>editable(c=>{if(Object.hasOwn(purposes,b.dataset.crPurpose)){c.work.purpose=b.dataset.crPurpose;show(`[data-cr-purpose="${c.work.purpose}"]`);}}));
 each('[data-cr-worked]',()=>{const c=active(s,state);if(!c)return;const helper=C.compareWorked(c.work.source);if(!helper||!c.mutable&&!c.work.workedSeen)return;c.ui.workedOpen=!c.ui.workedOpen;if(c.mutable&&c.ui.workedOpen)c.work.workedSeen=Math.max(c.work.workedSeen,c.ui.step+1);show(c.ui.workedOpen?'#cr-teaching-heading':'[data-cr-worked]');});
 each('[data-cr-step]',b=>editable(c=>{const helper=C.compareWorked(c.work.source),step=c.ui.step+Number(b.dataset.crStep);if(helper&&Number.isInteger(step)&&step>=0&&step<helper.steps.length){c.ui.step=step;c.work.workedSeen=Math.max(c.work.workedSeen,step+1);const direction=step===0?1:step===helper.steps.length-1?-1:Number(b.dataset.crStep);show(C.isReferenceScaleMode(c.work.source)?`[data-cr-step="${direction}"]:not(:disabled)`:'#cr-teaching-heading');}}));
 each('[data-cr-keep]',()=>editable(c=>{const id=C.keepComparison(state,c.work,{canExport:ctx.canExport});if(!id){const view=C.compareRecordsView(state);s.notice=view.status==='unsupported'?'Earlier comparisons stay in your notes. This format cannot accept another kept comparison here.':!view.canKeep?'Your earlier comparisons are safe. This notebook cannot keep another here. You can keep exploring in this visit and download your notes.':'This comparison could not be kept. Nothing was changed. Your choices are still here. Open Grown-up notes to download your work.';show('#cr-status',true);return;}s.slots.delete(c.slot);s.keptUI.set(id,{...c.ui,workedOpen:false});s.current={kind:'kept',id};const saved=ctx.save?.();s.notice=saved?.enabled===false?'Comparison kept for this session. Saving on this device is off.':saved?.ok===false?'This comparison is in this session, but it could not be saved on this device. Download your notes.':'Comparison kept. Its original records and your choices stay together.';show('#cr-status',true);}));
 root.querySelector('[data-cr-source-fold]')?.addEventListener('toggle',event=>{if(live(event.target)){const c=active(s,state);if(c)c.ui.sourceOpen=event.target.open;ctx.stopSpeech?.();}});
 root.addEventListener('click',event=>{
  const hear=event.target.closest?.('[data-cr-hear]');if(!hear)return;const c=active(s,state);if(!live(hear)||!c){event.preventDefault();event.stopImmediatePropagation();return;}
  if(c.mutable)c.work.narration=true;const controls=root.querySelector('.speech-controls');if(controls)root.append(controls);
  const turn=root.querySelector('[data-cr-turn]'),numbers=[...turn.querySelectorAll('[data-cr-number]')].map(node=>[node,node.textContent]);
  try{for(const [node]of numbers)node.textContent=node.dataset.crSay;hear.dataset.speak=turn.innerText.replaceAll('×',' times ').replaceAll('÷',' divided by ').replaceAll('−',' minus ').replaceAll('+',' plus ');}finally{for(const [node,text]of numbers)node.textContent=text;}
 },true);
}

// Adult comparison notes only; never rendered as a child activity.
export function compareNotes(state){
 if(!Object.hasOwn(state,'compareRecords'))return '';
 try{const view=C.compareRecordsView(state);return `<details class="cr-notes"><summary>The Compare Shelf · kept comparisons</summary><p>Selected highlights, purposes, secondary comparisons and supplied teaching for invented records. No graded recommendation, captured spoken/paper response, independent-calculation evidence, safety prediction or story contribution. Given arithmetic qualifies matching waiting work without recall attempts. Unkept work is visit-only.</p>${view.items.filter(i=>i.readable).map(i=>C.isReferenceScaleMode(i.raw.source)?`<section><h3>Comparison ${i.index+1} · ${esc(i.raw.source.title)}</h3><p>${esc(referenceGrownup)}</p><p>Reference panel: ${i.raw.referenceView.referenceShown}; adjustment panel: ${i.raw.referenceView.adjustmentShown}; adjustment: ${esc(referenceSignedText(i.raw.referenceView.adjustment))} g; check panel: ${i.raw.referenceView.checkShown}; workings shown: ${i.raw.workingsShown}; teaching extent: ${i.raw.workedSeen}; narration requested: ${i.raw.narration}.</p></section>`:`<p>${esc(i.raw.source.title)} · ${esc(i.id)}. Highlight: ${esc(i.raw.focus)}; purpose: ${esc(i.raw.purpose||'not selected')}; set aside: ${i.raw.aside}; workings shown: ${i.raw.workingsShown}; secondary workings disclosed: ${i.raw.secondaryWorkingsSeen}; teaching extent: ${i.raw.workedSeen}; narration requested: ${i.raw.narration}.</p>`).join('')}<details><summary>Original comparison notes, including retained unreadable values</summary><pre>${esc(JSON.stringify(state.compareRecords,null,2))}</pre></details></details>`;}catch{return '<p>Earlier comparison notes retained unchanged in the download.</p>';}
}
// End adult comparison notes.
